package com.bank.tags.service;

import com.bank.tags.dto.TagReport;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.stream.*;

@Service
@Slf4j
public class TagService {

    // Multi-level data model: Customer → Accounts → Transactions → Tags
    record Transaction(String txnId, String description, List<String> tags,
                       Optional<String> riskNote) {}
    record Account(String accountId, List<Transaction> transactions) {}
    record Customer(String customerId, List<Account> accounts) {}

    private final List<Customer> customers = List.of(
        new Customer("CUST-001", List.of(
            new Account("SAV2001", List.of(
                new Transaction("T1", "Salary", List.of("CREDIT", "SALARY", "DOMESTIC"),
                    Optional.empty()),
                new Transaction("T2", "Wire to Nigeria", List.of("DEBIT", "WIRE", "INTERNATIONAL", "HIGH_RISK"),
                    Optional.of("Flagged: high-risk country")),
                new Transaction("T3", "Grocery", List.of("DEBIT", "POS", "DOMESTIC"),
                    Optional.empty())
            )),
            new Account("CUR3001", List.of(
                new Transaction("T4", "Client Payment", List.of("CREDIT", "WIRE", "BUSINESS"),
                    Optional.of("Large transaction")),
                new Transaction("T5", "Rent", List.of("DEBIT", "NEFT", "DOMESTIC"),
                    Optional.empty())
            ))
        )),
        new Customer("CUST-002", List.of(
            new Account("SAV2002", List.of(
                new Transaction("T6", "SIP Investment", List.of("DEBIT", "AUTO", "INVESTMENT"),
                    Optional.empty())
            ))
        ))
    );

    public TagReport generateTagReport() {
        List<String> useCases = new ArrayList<>();

        // ═══ USE CASE 1: Flatten nested collections (3 levels deep) ═══
        List<String> allTags = customers.stream()
            .flatMap(c -> c.accounts().stream())           // customers → accounts
            .flatMap(a -> a.transactions().stream())       // accounts → transactions
            .flatMap(t -> t.tags().stream())                // transactions → tags
            .toList();
        useCases.add("UC1 nested: " + customers.size() + " customers → " + allTags.size() + " total tags");

        // Unique sorted tags
        List<String> uniqueTags = allTags.stream().distinct().sorted().toList();

        // Tag frequency
        Map<String, Long> tagFreq = allTags.stream()
            .collect(Collectors.groupingBy(t -> t, Collectors.counting()));

        // ═══ USE CASE 2: Split CSV-like data ═══
        List<String> csvLines = List.of("RELIANCE,TCS,HDFC", "INFY,WIPRO", "BAJAJ");
        List<String> symbols = csvLines.stream()
            .flatMap(line -> Arrays.stream(line.split(",")))
            .toList();
        useCases.add("UC2 split: " + csvLines.size() + " CSV lines → " + symbols.size() + " symbols: " + symbols);

        // ═══ USE CASE 3: Optional::stream — extract risk notes ═══
        List<String> riskNotes = customers.stream()
            .flatMap(c -> c.accounts().stream())
            .flatMap(a -> a.transactions().stream())
            .map(Transaction::riskNote)              // Stream<Optional<String>>
            .flatMap(Optional::stream)                // Stream<String> — empties removed!
            .toList();
        useCases.add("UC3 Optional: 6 transactions → " + riskNotes.size() + " risk notes: " + riskNotes);

        // ═══ USE CASE 4: Merge multiple stream sources ═══
        Stream<String> source1 = Stream.of("RELIANCE", "TCS");
        Stream<String> source2 = Stream.of("HDFC", "INFY");
        Stream<String> source3 = Stream.of("WIPRO");
        List<String> merged = Stream.of(source1, source2, source3)
            .flatMap(s -> s)                          // Stream<Stream<String>> → Stream<String>
            .toList();
        useCases.add("UC4 merge: 3 stream sources → " + merged.size() + " total: " + merged);

        // ═══ USE CASE 5: One-to-many expansion ═══
        List<String> expanded = List.of(3, 1, 2).stream()
            .flatMap(n -> Stream.generate(() -> "").limit(n))  // 3→, 1→, 2→
            .toList();
        useCases.add("UC5 expand: [3,1,2] → " + expanded.size() + " stars: " + String.join("", expanded));

        int accountCount = customers.stream()
            .flatMap(c -> c.accounts().stream())
            .mapToInt(a -> 1).sum();
        int txnCount = customers.stream()
            .flatMap(c -> c.accounts().stream())
            .flatMap(a -> a.transactions().stream())
            .mapToInt(t -> 1).sum();

        return new TagReport(customers.size(), accountCount, txnCount,
            allTags.size(), uniqueTags, tagFreq, useCases);
    }
}
