package com.bank.tags.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class FlatMapUseCasesTest {

    @Test
    void uc1_flattenNestedCollections() {
        List<List<String>> nested = List.of(List.of("A", "B"), List.of("C"), List.of("D", "E"));
        List<String> flat = nested.stream().flatMap(Collection::stream).toList();
        assertThat(flat).containsExactly("A", "B", "C", "D", "E");
    }

    @Test
    void uc2_splitCsvToTokens() {
        List<String> tokens = Stream.of("X,Y,Z", "A,B")
            .flatMap(s -> Arrays.stream(s.split(","))).toList();
        assertThat(tokens).containsExactly("X", "Y", "Z", "A", "B");
    }

    @Test
    void uc3_optionalStreamExtractsPresent() {
        List<String> present = Stream.of(
            Optional.of("A"), Optional.empty(), Optional.of("B"), Optional.empty()
        ).flatMap(Optional::stream).toList();
        assertThat(present).containsExactly("A", "B");
    }

    @Test
    void uc4_mergeMultipleStreams() {
        List<String> merged = Stream.of(Stream.of("A"), Stream.of("B", "C"), Stream.of("D"))
            .flatMap(s -> s).toList();
        assertThat(merged).containsExactly("A", "B", "C", "D");
    }

    @Test
    void uc5_oneToManyExpansion() {
        List<String> expanded = Stream.of(2, 0, 3)
            .flatMap(n -> Stream.generate(() -> "").limit(n))
            .toList();
        assertThat(expanded).hasSize(5);  // 2+0+3
    }

    @Test
    void uc_multiLevelDrillDown() {
        record Fee(String type) {}
        record Trade(String id, List<Fee> fees) {}
        record Account(String id, List<Trade> trades) {}

        List<Account> accounts = List.of(
            new Account("A1", List.of(
                new Trade("T1", List.of(new Fee("BROKERAGE"), new Fee("GST"))),
                new Trade("T2", List.of(new Fee("STAMP_DUTY")))
            )),
            new Account("A2", List.of(
                new Trade("T3", List.of(new Fee("BROKERAGE")))
            ))
        );

        List<String> allFeeTypes = accounts.stream()
            .flatMap(a -> a.trades().stream())        // accounts → trades
            .flatMap(t -> t.fees().stream())           // trades → fees
            .map(Fee::type)
            .toList();

        assertThat(allFeeTypes).containsExactly("BROKERAGE", "GST", "STAMP_DUTY", "BROKERAGE");
    }
}
